139		}
140		// sendDone must never be lost: when the channel is full the oldest message
141		// is dropped to make room. The producer is the only sender, so one drop
142		// frees a slot for good.
143		sendDone := func(m tea.Msg) {
144			for range 2 {
145				select {
146				case out <- m:
147					return
148				default:
149				}
150				select {
151				case <-out:
152				default:
153				}
154			}
155		}
156	
157		addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
158		if err != nil {
159			if ctx.Err() == nil { // esc during the resolution is not an error
160				log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
161			}
162			sendDone(pathDoneMsg{gen: gen, err: err})
163			return
164		}
165		// The route is asked for the address actually traced. A failure is not
166		// fatal and is never shown: the trace goes on without the route column.
167		route, routeErr := e.route(ctx, addr)
168		if routeErr != nil && ctx.Err() == nil {
169			log.Printf("ERROR [netdiag/path] route %s: %v", tg.Host, routeErr)
170		}
171		ctr, ctrErr := inspectPathSource(ctx, src, resolveTimeout, e)
172		send(pathResolvedMsg{gen: gen, addr: addr, route: route, routeErr: routeErr, source: src, ctr: ctr, ctrErr: ctrErr})
173	
174		res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
175			send(pathHopMsg{gen: gen, hop: h})
176		})
177		if err != nil {
178			log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
179		}
180		sendDone(pathDoneMsg{gen: gen, result: res, err: err})
181	}
182	
183	// inspectPathSource reads the chosen container's network under its own
184	// timeout. This machine reads nothing. A failure is not fatal and is never
185	// shown: the raw error goes to the log unless the run was canceled.
186	func inspectPathSource(ctx context.Context, src pathSource, timeout time.Duration, e pathEngine) (docker.ContainerNetworking, error) {
187		if src.isHost() {
188			return docker.ContainerNetworking{}, nil
189		}
190		ictx, cancel := context.WithTimeout(ctx, timeout)
191		defer cancel()
192		ctr, err := e.inspect(ictx, src.ID)
193		if err != nil && ctx.Err() == nil {
194			log.Printf("ERROR [netdiag/path] inspect %s: %v", src.ID, err)
195		}
196		return ctr, err
197	}
198	
199	// resolvePathTarget returns the IPv4 address to trace: a literal is used as
200	// is, a name is resolved under its own timeout.
201	func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
202		if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
203			return a, nil
204		}
205		rctx, cancel := context.WithTimeout(ctx, timeout)
206		defer cancel()
207		addrs, err := e.resolve(rctx, host)
208		if err != nil {
209			return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
210		}
211		if len(addrs) == 0 {
212			return netip.Addr{}, errPathNoIPv4
213		}
214		return addrs[0], nil
215	}
216	
217	// waitForPathMsg returns a Cmd that yields the next message of in, or nil
218	// once in is closed. The view re-arms it after every message.
219	func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
220		return func() tea.Msg {
221			m, ok := <-in
222			if !ok {
223				return nil
224			}
225			return m
226		}
227	}
